def lookup(br12: str, br23: str) -> Optional[FrozenSet[str]]:
    """Returns the Z-table result set for (br12, br23), or None."""
    return _Z.get(br12 + "|" + br23)


def get_table() -> Dict[str, FrozenSet[str]]:
    """Returns an immutable view of the full Z table."""
    return dict(_Z)
